#!/usr/bin/env bash
# Regenerates the pkix-dane test fixtures and their digest manifest.
#
# Fixtures:
#   leaf, other        two unrelated self-signed certificates, for the
#                      end-entity usages and for negative tests
#   ca, chain-leaf     a real CA and a certificate it issued, for the
#                      trust-anchor usages — DANE-TA matches a record
#                      against a certificate above the leaf, which two
#                      unrelated self-signed certificates cannot exercise
#
# DANE matching never inspects a signature, an issuer or a validity date,
# so these certificates need no particular properties beyond being
# distinct and parseable.
#
# digests.txt is the manifest the tests read. The digests come from
# `openssl dgst`, never from this crate's own sha2: a test that computes
# its expectation with the code under test proves only self-consistency.
# Writing them to a file rather than hardcoding them in the test source
# means regenerating the fixtures cannot leave stale expectations behind —
# new keys are generated on every run, so every digest changes.
set -euo pipefail
cd "$(dirname "$0")"

self_signed() {
  local name="$1" cn="$2"
  shift 2
  openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 \
    -keyout "${name}.key.pem" -out "${name}.pem" \
    -days 3650 -nodes -subj "/CN=${cn}" "$@" 2>/dev/null
  openssl x509 -in "${name}.pem" -outform DER -out "${name}.der"
}

spki() {
  openssl x509 -in "$1.der" -inform DER -noout -pubkey \
    | openssl pkey -pubin -outform DER -out "$1.spki.der"
}

self_signed leaf  "dane-test-leaf.example.com"
self_signed other "dane-test-other.example.com"
self_signed ca    "dane-test-ca.example.com" \
  -addext "basicConstraints=critical,CA:TRUE" \
  -addext "keyUsage=critical,keyCertSign,cRLSign"

openssl req -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 \
  -keyout chain-leaf.key.pem -out chain-leaf.csr.pem -nodes \
  -subj "/CN=dane-test-chained.example.com" 2>/dev/null
openssl x509 -req -in chain-leaf.csr.pem -CA ca.pem -CAkey ca.key.pem \
  -days 3650 -out chain-leaf.pem \
  -extfile <(printf 'subjectAltName=DNS:dane-test-chained.example.com\n') 2>/dev/null
openssl x509 -in chain-leaf.pem -outform DER -out chain-leaf.der

for name in leaf other ca chain-leaf; do
  spki "$name"
done
rm -f ./*.pem

# A certificate whose validity dates are GeneralizedTime even though they
# are before 2050. OpenSSL will not emit one (RFC 5280 §4.1.2.5 says to use
# UTCTime there), so it is assembled by rewriting leaf.der's time fields.
# This is the only fixture that exercises the hazard the Cert selector's
# byte-exactness rule exists for: x509-cert 0.3 normalizes such a date back
# to UTCTime on re-encode, so a digest taken over to_der() output would not
# match the certificate's own TLSA record. Not validly signed, and does not
# need to be -- DANE matching compares octets and never checks signatures.
python3 -I gen_gentime.py leaf.der gentime-leaf.der
spki gentime-leaf

{
  echo "# Generated by gen.sh. Digests from openssl dgst, not from pkix-dane."
  echo "# Columns: fixture selector algorithm hex-digest"
  for name in leaf other ca chain-leaf gentime-leaf; do
    for pair in "der Cert" "spki.der Spki"; do
      set -- $pair
      for alg in sha256 sha512; do
        printf '%s %s %s %s\n' "$name" "$2" "$alg" \
          "$(openssl dgst -"${alg}" -hex < "${name}.$1" | sed 's/^.*= //')"
      done
    done
  done
} > digests.txt

echo "regenerated $(ls ./*.der | wc -l) DER fixtures and digests.txt"
